SELECT s.id, s.nickname, s.look_theme, s.look_companion,
    (s.status='ACTIVE' AND s.community_enabled AND ) AS visible
FROM student s WHERE s.id IN #{id}

SELECT DISTINCT target_id FROM error_report WHERE target_type='COMMUNITY_POST'
AND target_id IN #{id}
AND (status <> 'RESOLVED' OR review_result IS DISTINCT FROM 'VISIBLE')
